item.command:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command "@'
import fs from 'node:fs';
const data=JSON.parse(fs.readFileSync('data/roboarena_sessions.json','utf8'));
const pairs=data.flatMap(s=>{const a=Object.values(s.policies);const b=a.find(p=>p.name==='pi0_fast_droid');const c=a.find(p=>p.name==='paligemma_fast_specialist_droid');return b&&c?[{instr:s.instr,d:c.progress-b.progress,notes:s.notes}]:[]});
const discovery=pairs.slice(0,Math.floor(pairs.length/2));
console.log(JSON.stringify({pairs:pairs.length,discovery:discovery.length,worst:discovery.toSorted((a,b)=>a.d-b.d).slice(0,30).map(p=>({...p,notes:p.notes.slice(0,240)}))},null,2));
'@ | node --input-type=module"

